<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)($_POST['amount']??0);if($amount<100){flash('error','Minimum funding amount is ₦100.');header('Location:/wallet.php');exit;}try{$ref='STE-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$pdo->prepare('INSERT INTO funding_transactions(user_id,reference,amount,status) VALUES(?,?,?,?)')->execute([$u['id'],$ref,$amount,'pending']);$ps=new Paystack($config['paystack']['secret_key'],$config['app_url']);$r=$ps->initialize($u['email'],$amount,$ref);$url=$r['data']['authorization_url']??null;if(!$url)throw new RuntimeException('Could not create payment link.');header('Location:'.$url);exit;}catch(Throwable $e){flash('error',$e->getMessage());header('Location:/wallet.php');exit;}}
$s=$pdo->prepare('SELECT balance FROM wallets WHERE user_id=?');$s->execute([$u['id']]);$w=$s->fetch();$t=$pdo->prepare('SELECT * FROM wallet_transactions WHERE user_id=? ORDER BY id DESC LIMIT 20');$t->execute([$u['id']]);require __DIR__.'/../app/layout.php';header_html('Wallet');?><div class="grid two"><div class="card"><p class="eyebrow">Available balance</p><div class="balance"><?=money($w['balance']??0)?></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Amount (₦)</label><input type="number" name="amount" min="100" step="1" required></div><button class="btn">Fund with Paystack</button></form><p class="muted">Your payment is verified on the server before crediting the wallet.</p></div><div class="card"><h3>Wallet activity</h3><div class="table-wrap"><table><tr><th>Date</th><th>Type</th><th>Amount</th><th>Status</th></tr><?php foreach($t as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['type'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></div></div><?php footer_html();
